effect.shader:
vec4 u_xlat0;
vec4 u_xlat1;
bvec2 u_xlatb1;
vec2 u_xlat2;
bvec2 u_xlatb2;
vec4 u_xlat3;
vec4 u_xlat4;
vec4 u_xlat5;
float u_xlat7;
vec2 u_xlat12;
vec2 u_xlat13;
bvec2 u_xlatb13;
float u_xlat18;
bool u_xlatb18;
void main()
{
    u_xlat0.xy = (-vec2(_end.x, _end.y)) + _start.xy;
    u_xlat12.xy = acScreenNorm.xy + (-vec2(_end.x, _end.y));
    u_xlat1.x = dot(u_xlat12.xy, u_xlat0.xy);
    u_xlat7 = dot(u_xlat0.xy, u_xlat0.xy);
    u_xlat1.x = u_xlat1.x / u_xlat7;
    u_xlat1.x = clamp(u_xlat1.x, 0.0, 1.0);
    u_xlat13.xy = u_xlat0.xy * u_xlat1.xx;
    u_xlat12.xy = (-u_xlat1.xx) * u_xlat0.xy + u_xlat12.xy;
    u_xlat12.x = dot(u_xlat12.xy, u_xlat12.xy);
    u_xlat12.x = sqrt(u_xlat12.x);
    u_xlat18 = float(1.0) / _radius;
    u_xlat12.x = u_xlat18 * u_xlat12.x;
    u_xlat12.x = clamp(u_xlat12.x, 0.0, 1.0);
    u_xlat18 = u_xlat12.x * -2.0 + 3.0;
    u_xlat12.x = u_xlat12.x * u_xlat12.x;
    u_xlat12.x = (-u_xlat18) * u_xlat12.x + 1.0;
    u_xlat18 = sqrt(u_xlat7);
    u_xlat1.x = dot(u_xlat13.xy, u_xlat13.xy);
    u_xlat1.x = sqrt(u_xlat1.x);
    u_xlat18 = float(1.0) / u_xlat18;
    u_xlat18 = u_xlat18 * u_xlat1.x;
    u_xlat18 = clamp(u_xlat18, 0.0, 1.0);
    u_xlat1.x = u_xlat18 * -2.0 + 3.0;
    u_xlat18 = u_xlat18 * u_xlat18;
    u_xlat18 = (-u_xlat1.x) * u_xlat18 + 1.0;
    u_xlat1.x = inversesqrt(u_xlat7);
    u_xlat0.xy = u_xlat0.xy * u_xlat1.xx;
    u_xlat0.xy = u_xlat12.xx * u_xlat0.xy;
    u_xlat0.xy = vec2(u_xlat18) * u_xlat0.xy;
    u_xlat0.xy = u_xlat0.xy * vec2(_strength);
    u_xlat0.xy = u_xlat0.xy * vec2(0.300000012, 0.300000012) + acScreenNorm.xy;
    u_xlatb1.xy = lessThan(u_xlat0.xyxx, vec4(0.0, 0.0, 0.0, 0.0)).xy;
    u_xlatb13.xy = lessThan(vec4(1.0, 1.0, 1.0, 1.0), u_xlat0.xyxy).xy;
    u_xlatb18 = u_xlatb13.x || u_xlatb1.x;
    u_xlatb18 = u_xlatb1.y || u_xlatb18;
    u_xlatb18 = u_xlatb13.y || u_xlatb18;
    u_xlat0.z = (u_xlatb18) ? 0.0 : 1.40129846e-45;
    u_xlatb18 = int(_keep_edge)==1;
    u_xlat2.xy = fract(u_xlat0.xy);
    u_xlat2.xy = (-u_xlat2.xy) + vec2(1.0, 1.0);
    u_xlat13.x = (u_xlatb13.x) ? u_xlat2.x : u_xlat0.x;
    u_xlat13.y = (u_xlatb13.y) ? u_xlat2.y : u_xlat0.y;
    u_xlat1.x = (u_xlatb1.x) ? (-u_xlat0.x) : u_xlat13.x;
    u_xlat1.y = (u_xlatb1.y) ? (-u_xlat0.y) : u_xlat13.y;
    u_xlat1.z = 1.40129846e-45;
    u_xlat0.xyz = (bool(u_xlatb18)) ? u_xlat1.xyz : u_xlat0.xyz;
    u_xlat1 = texture(inputImg, u_xlat0.xy);
    u_xlat0.x = float(floatBitsToInt(u_xlat0.z));
    u_xlat0 = u_xlat0.xxxx * u_xlat1;
    if(int(_use_inner_mask) != 0) {
        u_xlat1 = texture(inputImg, acScreenNorm.xy);
        u_xlatb2.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        u_xlat3 = (u_xlatb2.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat0;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat1 = u_xlat1 * u_xlat5;
        u_xlat1 = u_xlat3 * u_xlat4 + u_xlat1;
        u_xlat2.x = u_xlat4.x * u_xlat1.w;
        fragColor.w = (u_xlatb2.y) ? u_xlat2.x : u_xlat1.w;
        fragColor.xyz = u_xlat1.xyz;
    } else {
        fragColor = u_xlat0;
    }
    return;
}
